function tira(c, text, rel) {
  const hunks = c.desfaz[rel]
  if (!hunks || !text.includes(c.marca)) return text
  for (const h of hunks) {
    const parts = text.split(h.now.join('\n'))
    if (parts.length !== 2) throw new Error('desfaz ' + c.marca + ': ' + rel + ' mudou fora da camada (' + (parts.length - 1) + 'x)')
    text = parts.join(h.before.join('\n'))
  }
  if (text.includes(c.marca)) throw new Error('desfaz ' + c.marca + ': sobrou linha marcada em ' + rel)
  return text
}
function desde(idx, text, rel) {
  if (typeof text !== 'string') return text
  rel = String(rel ?? '').replace(/\\/g, '/')
  if (!CAMADAS.some((c, i) => i >= idx && c.desfaz[rel])) return text
  const crlf = text.includes('\r\n')
  let s = text.replace(/\r\n/g, '\n')
  for (let j = CAMADAS.length - 1; j >= idx; j--) s = tira(CAMADAS[j], s, rel)
  return crlf ? s.replace(/\n/g, '\r\n') : s
}
